"""Explicit retry review in the existing authenticated workbench; no auto POST."""
JS = r'''
let dcRetry=null,dcRetryVersion=0,dcRetryIntents=new Map();
function dcRetryReset(connection=false){dcRetry=null;dcRetryVersion++;if(connection)dcRetryIntents.clear();}
function dcRetryCurrent(c){return c===dcRetry&&c.session===dcSession&&c.jobVersion===dcJobVersion&&c.job===dcSelectedJob;}
const dcRetryReasons={not_explicit_unbound_source_error:'不是明确失败输入，保留原结果',duplicate_input_has_nonfailed_copy:'重复输入已有成功记录',returned_group_has_same_query_text:'相同关键词已有返回记录',source_error_with_saved_group_requires_narrower_source_retry:'已有部分结果，需要更窄的重试范围'};
function dcRetryUsable(c){return !!(dcRetryCurrent(c)&&c.quote&&Date.parse(c.quote.expires_at)>Date.now()&&c.quote.executor_available&&c.quote.budget_status==='configured'&&!c.busy&&!c.uncertain);}
function dcRetryReady(){const c=dcRetry,m=$('dcRetryMaximum'),ack=$('dcRetryConsent');return !!(c&&dcRetryUsable(c)&&m&&/^\d+(\.\d+)?$/.test(m.value)&&m.value.length<=100&&ack?.checked);}
function dcRetryControls(){if($('dcRetrySubmit'))$('dcRetrySubmit').disabled=!dcRetryReady();dcRetryExample();}
function dcRetryExample(){const c=dcRetry,pre=$('dcRetryExample');if(!pre||!c?.plan)return;const b={plan_hash:c.plan.plan_hash,budget:{maximum_cost:$('dcRetryMaximum')?.value||'YOUR_APPROVED_MAXIMUM',currency:c.quote?.currency||'SOURCE_CURRENCY'}},quoted=JSON.stringify(b).replaceAll("'","'\\''"),h='  -H "X-SearchFlow-Access-Key: $SEARCHFLOW_ACCESS_KEY" \\\n  -H "Authorization: Bearer $SEARCHFLOW_API_KEY"';pre.textContent=`curl '${location.origin}/v1/jobs/${c.job}/retry' \\\n${h}\n\n# 检查失败范围并批准新费用后，再显式提交\ncurl '${location.origin}/v1/jobs/${c.job}/retry' \\\n${h} \\\n  -H 'Idempotency-Key: your-unique-retry-1' \\\n  -H 'Content-Type: application/json' --data '${quoted}'\n\ncurl '${location.origin}/v1/jobs/CHILD_JOB_ID/lineage' \\\n${h}`;}
function dcRetryRender(c){if(!dcRetryCurrent(c))return;const p=c.plan,excluded=p.excluded.length?`<details><summary>保留原结果，不重试 ${p.excluded.length} 个输入</summary>${productTable(['原输入位置','状态','保留原因'],p.excluded.map(r=>`<tr><td>${r.input_index+1}</td><td>${esc(r.status)}</td><td>${esc(dcRetryReasons[r.reason]||r.reason)}</td></tr>`))}</details>`:'';
const selected=p.input_mapping.length?productTable(['原输入位置','仅重试这些关键词'],p.input_mapping.map(m=>`<tr><td>${m.parent_input_index+1}</td><td>${esc(m.requested_query)}</td></tr>`)):'';
let action='';if(p.existing_child_job_id)action=`<p>此固定观测已有重试任务，不会重复创建。</p><button type="button" data-dc-job="${esc(p.existing_child_job_id)}">查看已有子任务</button>`;
else if(!p.eligible)action='<p>没有可安全重试的失败输入。缺失月份、未出现、低量和已有结果不会自动重发。</p>';
else{const q=c.quote;action=`<p>新任务只包含 ${p.input_mapping.length} 个失败输入，原任务的成功结果和费用保留。</p>${selected}${q?`<p class="help">${esc(q.provider)} · ${esc(q.billing_unit)} · 获准整次上限 ${esc(q.maximum_cost)} ${esc(q.currency)}<br>${q.executor_available?'执行器可用':'执行器尚不可用'} · ${q.budget_status==='configured'?'已配置预算':'尚未配置预算'} · 预览有效至 ${esc(time(q.expires_at))}</p><div class="dc-form"><label>重试授权费用上限<input id="dcRetryMaximum" type="text" inputmode="decimal" autocomplete="off" placeholder="填写本次新费用上限"></label><label>重试币种<input id="dcRetryCurrency" readonly value="${esc(q.currency)}"></label></div><label class="dc-retry-consent"><input id="dcRetryConsent" type="checkbox"> 我已核对失败关键词，并授权本次新的费用上限</label><div class="dc-buttons"><button id="dcRetrySubmit" type="button" disabled>仅重试这些失败输入</button></div>`:`<p>${esc(c.quoteError||'尚未取得有效来源与费用预览，不能提交。')}</p>`}`;}
$('dcRetryPanel').innerHTML=`<div class="dc-detail"><h4>核对失败范围与新费用</h4>${action}${excluded}<p id="dcRetryStatus" role="status"></p><div class="dc-buttons"><button type="button" class="secondary" data-dc-retry="${esc(c.job)}">重新核验范围与结果</button></div><details><summary>固定父版本与重试依据</summary><pre>${esc(dcJson(p))}</pre></details><details><summary>重试 API 示例</summary><pre id="dcRetryExample" class="product-code"></pre><button type="button" class="secondary" data-dc-retry-copy>复制重试 API 示例</button></details></div>`;
for(const id of ['dcRetryMaximum','dcRetryConsent'])if($(id))$(id).addEventListener('input',dcRetryControls);dcRetryControls();
if(c.quote)setTimeout(()=>{if(dcRetryCurrent(c)){dcRetryControls();if(!dcRetryUsable(c)&&$('dcRetryStatus'))$('dcRetryStatus').textContent='预览已过期或当前不可提交，请重新核验。';}},Math.max(0,Math.min(2147483647,Date.parse(c.quote.expires_at)-Date.now()+20)));
}
async function dcRetryRead(job){if(job!==dcSelectedJob)return;const c={job,session:dcSession,jobVersion:dcJobVersion,version:++dcRetryVersion,busy:false,uncertain:false};dcRetry=c;$('dcRetryPanel').textContent='正在核验失败范围…';try{c.plan=await dcRequest('/v1/jobs/'+dcUrl(job)+'/retry');if(!dcRetryCurrent(c))return;if(c.plan.parent_job_id!==job)throw Error('父任务与当前选择不符');if(c.plan.eligible&&!c.plan.existing_child_job_id){$('dcRetryPanel').textContent='正在核验新任务来源与费用上限…';try{c.quote=await dcRequest('/v1/data/jobs/preview',c.plan.parameters);}catch(e){c.quoteError=e.message;}}if(dcRetryCurrent(c))dcRetryRender(c);}catch(e){if(dcRetryCurrent(c)){dcRetry=null;$('dcRetryPanel').textContent=e.message+'；请重新读取任务后核验。';}}}
async function dcRetrySubmit(){const c=dcRetry;if(!dcRetryReady())return;const payload={plan_hash:c.plan.plan_hash,budget:{maximum_cost:$('dcRetryMaximum').value,currency:c.quote.currency}},fingerprint=JSON.stringify([c.session,c.job,payload]);let intent=dcRetryIntents.get(fingerprint);if(!intent){intent={key:crypto.randomUUID()};dcRetryIntents.set(fingerprint,intent);}c.busy=true;dcRetryControls();for(const b of $('dcRetryPanel').querySelectorAll('button,input'))b.disabled=true;$('dcRetryStatus').textContent='正在创建失败输入子任务…';try{const j=await dcRequest('/v1/jobs/'+dcUrl(c.job)+'/retry',payload,{idempotency:intent.key});if(!dcRetryCurrent(c))return;if(j.retry?.parent_job_id!==c.job||j.retry?.plan_hash!==c.plan.plan_hash)throw Error('重试关联返回不符，请重新核验结果');c.created=j.id;$('dcRetryPanel').innerHTML=`<div class="dc-detail"><h4>重试子任务已受理</h4><p>仅重试已核对的失败输入；实际费用仍待执行确认。</p><div class="dc-buttons"><button type="button" data-dc-job="${esc(j.id)}">查看子任务进度与事实</button><button type="button" class="secondary" data-dc-retry="${esc(c.job)}">核验父版本关联</button></div><p class="dc-proof">子任务 ${esc(j.id)}<br>父观测 ${esc(c.plan.parent_observation_id)}</p></div>`;await dcLoad();}catch(e){if(dcRetryCurrent(c)){c.uncertain=true;$('dcRetryPanel').innerHTML=`<div class="dc-detail"><h4>请先核验重试结果</h4><p>${esc(e.message)}</p><p>写操作可能已保存。不会自动再次提交；重新核验后可查看已创建的子任务。</p><button type="button" class="secondary" data-dc-retry="${esc(c.job)}">重新核验范围与结果</button></div>`;}}finally{c.busy=false;}}
async function dcRetryLineage(job){if(job!==dcSelectedJob)return;const c={job,session:dcSession,jobVersion:dcJobVersion,version:++dcRetryVersion};dcRetry=c;$('dcRetryPanel').textContent='正在核验父子任务关联…';try{const p=await dcRequest('/v1/jobs/'+dcUrl(job)+'/lineage');if(!dcRetryCurrent(c))return;$('dcRetryPanel').innerHTML=p.is_retry?`<div class="dc-detail"><h4>失败子集重试关联</h4><p>本任务独立计费；原任务的成功结果与费用保留。</p><button type="button" class="secondary" data-dc-job="${esc(p.parent_job_id)}">查看原任务</button>${productTable(['本任务输入位置','原输入位置','关键词'],p.input_mapping.map(m=>`<tr><td>${m.child_input_index+1}</td><td>${m.parent_input_index+1}</td><td>${esc(m.requested_query)}</td></tr>`))}<details><summary>固定父版本与完整映射</summary><pre>${esc(dcJson(p))}</pre></details></div>`:'此任务不是失败子集重试任务。';}catch(e){if(dcRetryCurrent(c)){dcRetry=null;$('dcRetryPanel').textContent=e.message;}}}
$('dcJobDetail').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.dcRetry){b.disabled=true;try{await dcRetryRead(b.dataset.dcRetry);}finally{if(b.isConnected)b.disabled=false;}}else if(b.dataset.dcLineage){b.disabled=true;try{await dcRetryLineage(b.dataset.dcLineage);}finally{if(b.isConnected)b.disabled=false;}}else if(b.id==='dcRetrySubmit'){await dcRetrySubmit();}else if(b.hasAttribute('data-dc-retry-copy')){try{await navigator.clipboard.writeText($('dcRetryExample').textContent);notice('已复制两层鉴权占位符示例');}catch(e){notice('请手动选择示例文本复制',true);}}});
'''
